def below_zero(operations: list[int]) -> bool:
    balance = 0
    for op in operations:
        balance += op
        if balance < 0:
            return True
    return False

def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.
    """
    if not coeffs:
        return "0"
    terms = []
    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if coeff == 0:
            continue

        # Determine sign and coefficient string
        sign = ""
        if not terms:
            # First term: no leading plus; handle minus if coeff negative
            if coeff < 0:
                sign = "-"
        else:
            sign = "+" if coeff > 0 else "-"

        abs_coeff = abs(coeff)
        # Coefficient representation (skip '1' for variable terms)
        coeff_str = ""
        if abs_coeff != 1 or degree == 0:
            coeff_str = str(abs_coeff)

        # Variable part based on degree
        var_part = ""
        if degree > 1:
            var_part = f"x^{degree}"
        elif degree == 1:
            var_part = "x"

        terms.append(f"{sign}{coeff_str}{var_part}")

    if not terms:
        return "0"

    return "".join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    """
    Decodes an encrypted message using a cipher derived from a known encoded-original pair.

    The function builds a mapping from encoded letters to their original letters and
    uses this mapping to decode a given encrypted message. If a contradiction is found
    during mapping construction, the mapping does not contain all 26 letters, or not
    all letters in the encrypted message appear in the mapping, the function returns
    "Failed".
    """
    # Validate basic preconditions
    if len(encoded) != len(original):
        return "Failed"

    mapping = {}
    for enc_char, orig_char in zip(encoded, original):
        if enc_char in mapping:
            if mapping[enc_char] != orig_char:
                return "Failed"  # Contradictory mapping
        else:
            mapping[enc_char] = orig_char

    # Ensure the full alphabet is represented
    if len(mapping) != 26:
        return "Failed"

    # Decode the message
    decoded_chars = []
    for m_char in message:
        if m_char not in mapping:
            return "Failed"  # Unmapped character
        decoded_chars.append(mapping[m_char])

    return "".join(decoded_chars)

def minimum_students_to_leave(heights):
    """
    Calculate the minimum number of students that need to leave to form a choir formation.
    A choir formation is defined such that for some position 'i', the heights of students
    increase from the start to 'i' and decrease from 'i' to the end of the formation.

    Args:
    heights (List[int]): A list of student heights.

    Returns:
    int: The minimum number of students that need to leave.
    """
    if not isinstance(heights, list):
        raise TypeError("heights must be a list")
    n = len(heights)
    if n <= 1:
        return 0

    # Longest increasing subsequence ending at each index
    lis = [1] * n
    for i in range(n):
        for j in range(i):
            if heights[j] < heights[i] and lis[j] + 1 > lis[i]:
                lis[i] = lis[j] + 1

    # Longest decreasing subsequence starting at each index
    lds = [1] * n
    for i in range(n - 1, -1, -1):
        for j in range(i + 1, n):
            if heights[i] > heights[j] and lds[j] + 1 > lds[i]:
                lds[i] = lds[j] + 1

    # Longest bitonic subsequence length
    max_bitonic = 0
    for i in range(n):
        length = lis[i] + lds[i] - 1  # peak counted twice
        if length > max_bitonic:
            max_bitonic = length

    # Minimum removals
    return n - max_bitonic
